insert into public.threads(id,author_id,title,topics) values('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Моя перша фотокнига',array['Фото','Дизайн']);
insert into public.posts(id,author_id,body,media,topics,thread_id,part,created_at) values
('30000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Збираю свою першу фотокнигу. Починаю з маленького — світла, тіней і випадкових зустрічей.','[{"src":"/media/photobook.webp","path":"","type":"image/webp"}]',array['Фото','Дизайн'],'20000000-0000-4000-8000-000000000001',1,now()-interval '25 minutes'),
('30000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002','Записую звуки міста для нового треку. Дивовижно, скільки музики навколо, якщо просто трохи прислухатися.','[{"src":"https://images.unsplash.com/photo-1598488035139-bdbb2231ce04?w=1000&h=400&fit=crop","path":"","type":"image/jpeg"}]',array['Музика'],null,null,now()-interval '1 hour'),
('30000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000003','Сьогодні моя перша чашка нарешті витримала випал. Вона трохи крива, але саме тому я її люблю. З чого почався ваш творчий тиждень?','[]',array['Кераміка','Мистецтво'],null,null,now()-interval '2 hours'),
('30000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000001','Відібрала перші 12 кадрів. Помітила, що всі вони про тихі моменти між справами. Здається, знайшла тему для книги.','[]',array['Фото','Дизайн'],'20000000-0000-4000-8000-000000000001',2,now()-interval '3 hours');
insert into public.series(id,author_id,title,thread_id) values('40000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','За кадром фотокниги','20000000-0000-4000-8000-000000000001');
insert into public.stories(author_id,media,caption,series_id,post_id,created_at,expires_at) values
('10000000-0000-4000-8000-000000000001','{"src":"/media/photobook.webp","path":"","type":"image/webp"}','Перші відбитки. Усе починається з одного кадру.','40000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001',now()-interval '1 hour',now()+interval '23 hours'),
('10000000-0000-4000-8000-000000000002','{"src":"https://images.unsplash.com/photo-1598488035139-bdbb2231ce04?w=700&fit=crop","path":"","type":"image/jpeg"}','Шукаю звучання для нового треку.',null,null,now()-interval '2 hours',now()+interval '22 hours'),
('10000000-0000-4000-8000-000000000003','{"src":"https://images.unsplash.com/photo-1493106641515-6b5631de4bb9?w=700&fit=crop","path":"","type":"image/jpeg"}','Повільний ранок у майстерні.',null,null,now()-interval '3 hours',now()+interval '21 hours');
